<?xml version="1.0" encoding="UTF-8"?>
<ArdourMIDIBindings version="1.0.0" name="KeyLab Essential Cue + Mix" manufacturer="Arturia">
  <!--
    Original KeyLab Essential User map, written by
    keylab-essential-ardour-cue-map with its mixer-controls option.

    All control messages use MIDI channel 16, leaving channel 1 available for
    the keybed and notes 36-43 available for Cue Grid MIDI Learn.
  -->
  <DeviceInfo bank-size="8"/>

  <!-- Faders 1-8: gain of tracks/busses in the current eight-strip bank. -->
  <Binding channel="16" ctl="20" uri="/route/gain B1"/>
  <Binding channel="16" ctl="21" uri="/route/gain B2"/>
  <Binding channel="16" ctl="22" uri="/route/gain B3"/>
  <Binding channel="16" ctl="23" uri="/route/gain B4"/>
  <Binding channel="16" ctl="24" uri="/route/gain B5"/>
  <Binding channel="16" ctl="25" uri="/route/gain B6"/>
  <Binding channel="16" ctl="26" uri="/route/gain B7"/>
  <Binding channel="16" ctl="27" uri="/route/gain B8"/>
  <Binding channel="16" ctl="28" uri="/bus/gain master"/>

  <!-- Knobs 1-8: pan direction for the same bank. -->
  <Binding channel="16" ctl="70" uri="/route/pandirection B1"/>
  <Binding channel="16" ctl="71" uri="/route/pandirection B2"/>
  <Binding channel="16" ctl="72" uri="/route/pandirection B3"/>
  <Binding channel="16" ctl="73" uri="/route/pandirection B4"/>
  <Binding channel="16" ctl="74" uri="/route/pandirection B5"/>
  <Binding channel="16" ctl="75" uri="/route/pandirection B6"/>
  <Binding channel="16" ctl="76" uri="/route/pandirection B7"/>
  <Binding channel="16" ctl="77" uri="/route/pandirection B8"/>

  <!-- Knob 9: gain of the first send on the selected track (for example, FX). -->
  <Binding channel="16" ctl="78" uri="/route/send/gain S1 1"/>

  <!-- Assignable buttons: Part 1, Part 2, Live. -->
  <Binding channel="16" note="44" function="prev-bank"/>
  <Binding channel="16" note="45" function="next-bank"/>
  <Binding channel="16" note="46" function="toggle-rec-enable"/>
</ArdourMIDIBindings>
